<script setup lang="ts">
import { onMounted, ref } from 'vue'
import { apiClient } from '@/services/api'
import { useAuthStore } from '@/stores/auth'
import type { AttendanceRecord, EmployeeDashboard as Dashboard } from '@/types'
const auth = useAuthStore(); const dashboard = ref<Dashboard | null>(null); const loading = ref(false); const error = ref(''); const success = ref('')
const format = (value: string | null) => value ? new Date(value).toLocaleString() : '—'
async function load() { loading.value = true; error.value = ''; try { dashboard.value = await apiClient.getEmployeeDashboard() } catch (e) { error.value = apiClient.getErrorMessage(e) } finally { loading.value = false } }
async function punch(action: 'in' | 'out') { loading.value = true; error.value = ''; success.value = ''; try { const record: AttendanceRecord = action === 'in' ? await apiClient.checkIn() : await apiClient.checkOut(); if (dashboard.value) dashboard.value.today_status = record; success.value = action === 'in' ? 'Checked in successfully.' : 'Checked out successfully.'; await load() } catch (e) { error.value = apiClient.getErrorMessage(e) } finally { loading.value = false } }
onMounted(load)
</script>
<template><main class="space-y-6"><div><h1 class="text-2xl font-bold text-slate-900">Welcome</h1><p class="text-slate-500">{{ auth.user?.email }}</p></div><div v-if="error" class="rounded bg-red-50 p-3 text-red-700">{{ error }}</div><div v-if="success" class="rounded bg-green-50 p-3 text-green-700">{{ success }}</div><section class="rounded-lg bg-white p-6 shadow"><h2 class="mb-4 text-lg font-semibold">Today's attendance</h2><p class="mb-4 text-slate-600">{{ dashboard?.today_status?.status || (dashboard?.today_absent ? 'Absent' : 'Not checked in') }}</p><div class="flex gap-3"><button class="rounded bg-indigo-600 px-4 py-2 text-white disabled:opacity-50" :disabled="loading || !!dashboard?.today_status" @click="punch('in')">Check in</button><button class="rounded bg-slate-800 px-4 py-2 text-white disabled:opacity-50" :disabled="loading || !dashboard?.today_status?.check_in_at || !!dashboard?.today_status?.check_out_at" @click="punch('out')">Check out</button></div></section><section class="rounded-lg bg-white p-6 shadow"><h2 class="mb-4 text-lg font-semibold">Recent attendance</h2><div class="overflow-x-auto"><table class="min-w-full text-left text-sm"><thead><tr class="border-b"><th class="p-2">Date</th><th class="p-2">Check in</th><th class="p-2">Check out</th><th class="p-2">Status</th></tr></thead><tbody><tr v-for="row in dashboard?.recent_attendance" :key="row.id" class="border-b"><td class="p-2">{{ row.work_date }}</td><td class="p-2">{{ format(row.check_in_at) }}</td><td class="p-2">{{ format(row.check_out_at) }}</td><td class="p-2">{{ row.status }}</td></tr></tbody></table></div></section></main></template>
